from math import sqrt## It generates a series with even numbers -plus 1 at the beginning, since it represents the#fundamental frequency- with a number of elements that reflects the spectral density of a note.#### "numeroDeArmonicos" will be determined by the number of specimens in a species.def parciales_pares (numeroDeArmonicos=1):## The maximum number of harmonics is 500 since the 501st pair harmonic is the 1002nd, who's#frequency, given the lowest audible fundamental (20hz), is over the audible range#(20000hz).		if numeroDeArmonicos > 500:		numeroDeArmonicos = 500		## It constructs a series of even numbers plus one. 	parciales = []  # container for the list to be generated	par = 2		# first positive even number	contador = 0		# counter		while contador < numeroDeArmonicos:		parciales.append(par)		par = par+2		contador = contador+1	return parciales ##It generates a harmonic series with odd partials with a number of elements that reflects the spectral#density of a note.#### "numeroDeArmonicos" will be determined by the number of specimens in a species.def parciales_nones (numeroDeArmonicos=1):	## The maximum number of harmonics is 499 since the 500th odd harmonic is the 1001st, who's#frequency, given the lowest audible fundamental (20hz), is over the audible range#(20000hz).		if numeroDeArmonicos > 499:		numeroDeArmonicos = 499## It constructs a series of odd partials. 	parciales = [] # container for the list to be generated	non = 1		# first odd number	contador = 0		# counter		while contador < numeroDeArmonicos:		parciales.append(non)		non = non+2		contador = contador+1	return parciales## Generates a fibonacci sequence -with just a "1" at the beginning, since duplicating "1" implies#giving twice the weight to the fundamental pitch- with a number of elements that reflects the spectral#density of a note.#### "numeroDeArmonicos" will be determined by the number of specimens in a species.def parciales_fibonacci (numeroDeArmonicos=1):	## The maximum number of harmonics is 14 since the 15th fibonacci harmonic is 1597, who's#frequency, given the lowest audible fundamental (20hz), is over the audible range (20000hz).		if numeroDeArmonicos > 14:		numeroDeArmonicos = 14## It constructs a series of fibonacci partials without duplicating "1".		parciales = []  # container for the list to be generated	a = 1			# first fibonacci number	b = 1			# second fibonacci number	contador = 0		#counter		while contador < numeroDeArmonicos:		parciales.append(b)		a, b = b, a+b		contador = contador+1	return parciales		##Generates a prime number sequence -plus 1 at the beginning, since it represents the fundamental#frequency- with a number of elements that reflects the spectral density of a note.#### "numeroDeArmonicos" will be determined by the number of specimens in a species.def parciales_primos(numeroDeArmonicos=1):## The maximum number of harmonics is 168 since the 169th prime harmonic is 1009, who's#frequency, given the lowest audible fundamental (20hz), is over the audible range (20000hz).		if numeroDeArmonicos > 168:		numeroDeArmonicos = 168		## It constructs a series of prime partials plus "1" at the beginning.		parciales = []      # container for the list to be generated	candidato = 2		# candidate for being prime (starts with the first prime)	contador = 0		# counter	while contador < numeroDeArmonicos:		max_prueba = int(sqrt(candidato))+1		for x in range (2, max_prueba):			if candidato % x == 0:				candidato = candidato+1				break		else:			parciales.append(candidato)			candidato = candidato+1			contador = contador+1	return parciales